/*
 *  call-seq:
 *    bit_count -> integer
 *
 *  Returns the number of set bits (bits equal to 1) in the binary
 *  representation of +self+, also known as the population count or
 *  Hamming weight.
 *
 *    0.bit_count            # => 0
 *    1.bit_count            # => 1
 *    7.bit_count            # => 3
 *    0b10101.bit_count      # => 3
 *    255.bit_count          # => 8
 *    (2**1000).bit_count    # => 1
 *    (2**1000-1).bit_count  # => 1000
 *
 *  Raises an exception if +self+ is negative.
 *
 *    (-1).bit_count # Raises ArgumentError
 *
 */

VALUE
rb_int_bit_count(VALUE num)
{
    if (FIXNUM_P(num)) {
        return rb_fix_bit_count(num);
    }
    else if (RB_BIGNUM_TYPE_P(num)) {
        return rb_big_bit_count(num);
    }
    UNREACHABLE_RETURN(Qnil);
}

static VALUE
rb_fix_digits(VALUE fix, long base)
{
    VALUE digits;
    long x = FIX2LONG(fix);

    RUBY_ASSERT(x >= 0);

    if (base < 2)
        rb_raise(rb_eArgError, "invalid radix %ld", base);

    if (x == 0)
        return rb_ary_new_from_args(1, INT2FIX(0));

    digits = rb_ary_new();
    while (x >= base) {
        long q = x % base;
        rb_ary_push(digits, LONG2NUM(q));
        x /= base;
    }
    rb_ary_push(digits, LONG2NUM(x));

    return digits;
}

